:root{--bg:#070b16;--panel:#0d1425;--ink:#edf2ff;--muted:#8d98b7;--a:#786cff;--c:#25d9e8;--g:#39e69c;--r:#ff6475;--b:rgba(255,255,255,.1)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Arial,sans-serif}.page{min-height:100vh;padding:24px;background:radial-gradient(circle at 50% 15%,rgba(120,108,255,.14),transparent 40%),#070b16}.head,.bar,.map,.log,.cards{max-width:1400px;margin-left:auto;margin-right:auto}.head{display:flex;justify-content:space-between;align-items:end;gap:18px}.eyebrow{font-size:9px;font-weight:900;letter-spacing:1.6px;color:#a7b0ca}.live{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--g);box-shadow:0 0 15px var(--g);animation:p 1s infinite}.head h1{margin:7px 0 4px;font-size:clamp(28px,4vw,48px);letter-spacing:-2px}.head h1 span{color:var(--a)}.head p{margin:0;color:var(--muted);font-size:11px}.status{border:1px solid var(--b);border-radius:12px;padding:10px 13px;background:#ffffff08;font:800 10px Inter;white-space:nowrap}.status strong{font-family:'Roboto Mono';color:#fff}.bar{display:flex;gap:9px;align-items:center;margin-top:13px}.run{border:0;border-radius:10px;padding:10px 15px;background:linear-gradient(135deg,var(--a),var(--c));color:#fff;font-weight:900;font-size:11px;cursor:pointer}.run:disabled{opacity:.55}.bar span{color:var(--muted);font-size:10px}.map{height:600px;margin-top:13px;border:1px solid var(--b);border-radius:22px;position:relative;overflow:hidden;background-image:linear-gradient(#ffffff06 1px,transparent 1px),linear-gradient(90deg,#ffffff06 1px,transparent 1px);background-size:30px 30px}.map svg{position:absolute;inset:0;width:100%;height:100%}.edge{fill:none;stroke:#4d5b86;stroke-width:2;stroke-dasharray:7 8;opacity:.4}.edge.live{stroke:url(#flow);opacity:1;filter:url(#glow)}.packet{fill:#fff;filter:url(#glow)}.nodes{position:absolute;inset:0}.node{position:absolute;width:205px;min-height:88px;padding:13px 14px;border:1px solid #786cff55;border-radius:15px;background:#0d1425f5;box-shadow:0 14px 32px #0005;cursor:pointer;transition:.18s}.node.active{border-color:var(--a);box-shadow:0 0 0 1px #786cff33,0 0 32px #786cff22}.node.ok{border-color:#39e69c99}.node.fail{border-color:#ff647599}.node small{display:block;color:#8f99b8;font-size:8px;font-weight:900;letter-spacing:1.3px;margin-bottom:5px}.node b{font-size:13px}.node em{display:block;margin-top:5px;color:#7f8aa9;font-size:9px;font-style:normal}.front{left:3%;top:42%}.tools{left:25%;top:42%}.image{left:48%;top:12%}.kb{left:48%;top:42%}.article{left:48%;top:72%}.learning{left:72%;top:42%}.end{right:3%;top:42%;border-color:#25d9e866}.end small{color:var(--c)}.legend{position:absolute;left:20px;right:20px;bottom:16px;display:flex;justify-content:space-between;gap:8px;color:#7f8aa9;font-size:9px;font-weight:700}.log{margin-top:10px;padding:11px 13px;border:1px solid var(--b);border-radius:12px;background:#ffffff06;color:#aeb6d3;font:500 10px 'Roboto Mono';white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.log b{color:#fff}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:10px}.card{padding:11px 13px;border:1px solid var(--b);border-radius:12px;background:#ffffff06}.card small{display:block;color:#7f8aa9;font-size:8px;font-weight:900}.card b{display:block;margin-top:4px;font-size:10px}.card span{display:block;margin-top:3px;color:#8792b0;font:500 9px 'Roboto Mono'}@keyframes p{50%{opacity:.4;transform:scale(.8)}@media(max-width:900px){.page{padding:16px 12px}.head{align-items:flex-start;flex-direction:column}.bar{flex-wrap:wrap}.map{height:auto;padding:18px}.nodes{position:relative;display:grid;gap:12px}.node{position:relative!important;left:auto!important;right:auto!important;top:auto!important;width:100%}.map svg{display:none}.legend{position:relative;left:auto;right:auto;bottom:auto;margin-top:15px;flex-wrap:wrap}.cards{grid-template-columns:1fr}}
</style></head><body><main class="page"><header class="head"><div><div class="eyebrow"><i class="live"></i> SMARTTOOLZ / REAL LIVE ROUTES</div><h1>Full Site <span>Wire Connection</span></h1><p>Packets are created only from real same-origin HTTP requests. No random animation loop.</p></div><div class="status"><i class="live"></i> TESTED <strong id="count">0/<?=count($routes)?></strong></div></header><div class="bar"><button class="run" id="run">▶ Run Live Trace</button><span>Each successful request lights its real route; failed requests turn red.</span></div><section class="map"><svg viewBox="0 0 1400 600" preserveAspectRatio="none"><defs><linearGradient id="flow"><stop stop-color="#786cff"/><stop offset=".5" stop-color="#25d9e8"/><stop offset="1" stop-color="#39e69c"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><path class="edge" data-edge="front-tools" d="M210 300 H390"/><path class="edge" data-edge="tools-image" d="M595 300 C660 300 660 120 770 120 H820"/><path class="edge" data-edge="tools-kb" d="M595 300 H820"/><path class="edge" data-edge="tools-article" d="M595 300 C660 300 660 480 770 480 H820"/><path class="edge" data-edge="kb-learning" d="M1025 300 H1008"/><path class="edge" data-edge="image-end" d="M1025 120 H1160 V300 H1190"/><path class="edge" data-edge="learning-end" d="M1275 300 H1190"/><path class="edge" data-edge="article-end" d="M1025 480 H1160 V300 H1190"/><g id="packets" filter="url(#glow)"></g></svg><div class="nodes">
<?php foreach($routes as $r): ?><div class="node <?=htmlspecialchars($r['id'])?>" data-id="<?=htmlspecialchars($r['id'])?>" data-url="<?=htmlspecialchars($r['url'])?>"><small><?=htmlspecialchars($r['type'])?></small><b><?=htmlspecialchars($r['name'])?></b><em><?=htmlspecialchars($r['url'])?></em></div><?php endforeach; ?><div class="node end" data-id="end"><small>END</small><b>Response Delivered</b><em>Real HTTP response received</em></div></div><div class="legend"><span>● real request packet</span><span>Click node = open actual route</span><span>START → HTTP → END</span></div></section><div class="log" id="log"><b>READY</b> — press Run Live Trace.</div><section class="cards"><?php foreach($routes as $r): ?><div class="card"><small><?=htmlspecialchars($r['type'])?></small><b><?=htmlspecialchars($r['name'])?></b><span><?=htmlspecialchars($r['url'])?></span></div><?php endforeach; ?></section></main><script>
const routes=<?=json_encode($routes,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;const edges={front:['front-tools'],tools:['tools-image','tools-kb','tools-article'],image:['image-end'],kb:['kb-learning'],article:['article-end'],learning:['learning-end']};const qs=s=>document.querySelector(s),log=qs('#log'),count=qs('#count'),run=qs('#run'),packetLayer=qs('#packets');
function node(id,cls){const n=qs('.node[data-id="'+id+'"]');if(n){n.classList.remove('active','ok','fail');if(cls)n.classList.add(cls)}}function edge(name){const e=qs('.edge[data-edge="'+name+'"]');if(!e)return;e.classList.add('live');const p=document.createElementNS('http://www.w3.org/2000/svg','circle');p.setAttribute('r','5');p.setAttribute('class','packet');packetLayer.appendChild(p);const d=e.getAttribute('d');const len=e.getTotalLength();let start=null;function frame(t){if(!start)start=t;const k=Math.min((t-start)/900,1);const pt=e.getPointAtLength(len*k);p.setAttribute('cx',pt.x);p.setAttribute('cy',pt.y);if(k<1)requestAnimationFrame(frame);else p.remove()}requestAnimationFrame(frame)}
async function hit(url){const t=performance.now();try{const r=await fetch(url,{cache:'no-store',credentials:'same-origin'});return{ok:r.ok,status:r.status,ms:Math.round(performance.now()-t)}}catch(e){return{ok:false,status:0,ms:Math.round(performance.now()-t)}}}
async function trace(){run.disabled=true;document.querySelectorAll('.node').forEach(n=>n.classList.remove('active','ok','fail'));document.querySelectorAll('.edge').forEach(e=>e.classList.remove('live'));packetLayer.innerHTML='';let ok=0;for(const r of routes){node(r.id,'active');log.innerHTML='<b>REQUEST</b> '+r.url;const x=await hit(r.url);node(r.id,x.ok?'ok':'fail');if(x.ok){ok++;(edges[r.id]||[]).forEach(edge);log.innerHTML='<b>OK '+x.status+'</b> '+r.url+' — '+x.ms+' ms'}else log.innerHTML='<b>FAILED '+(x.status||'NETWORK')+'</b> '+r.url;count.textContent=ok+'/'+routes.length;await new Promise(res=>setTimeout(res,250))}node('end',ok===routes.length?'ok':'active');log.innerHTML=ok===routes.length?'<b>END</b> All real routes responded successfully.':'<b>END</b> '+ok+'/'+routes.length+' routes responded successfully.';run.disabled=false}
run.addEventListener('click',trace);document.querySelectorAll('.node[data-url]').forEach(n=>n.addEventListener('click',()=>location.href=n.dataset.url));
</script></body></html>
